def longest_subarray(nums, k):
    first = {0: -1}
    total = 0
    best = 0
    for i, v in enumerate(nums):
        total += v
        r = total % k
        if r in first:
            best = max(best, i - first[r])
        else:
            first[r] = i
    return best

